{"content":"const fs = require('fs');

function fail(msg) {
  process.stderr.write(`Error: ${msg}\n`);
  process.exit(1);
}

function main() {
  const filePath = process.argv[2];
  if (!filePath) {
    fail('Usage: node parse_tx.js <path_to_hex_file>');
  }

  let raw;
  try {
    raw = fs.readFileSync(filePath, 'utf8');
  } catch (e) {
    fail(`Cannot read file: ${e.message}`);
  }

  // Strip whitespace (spaces, newlines, tabs, etc.)
  const hex = raw.replace(/\s+/g, '').toLowerCase();

  if (hex.length === 0) {
    fail('Empty hex string');
  }
  if (hex.length % 2 !== 0) {
    fail('Malformed hex: odd length');
  }
  if (!/^[0-9a-f]*$/.test(hex)) {
    fail('Malformed hex: invalid characters');
  }

  const buf = Buffer.from(hex, 'hex');

  let offset = 0;

  function need(n) {
    if (offset + n > buf.length) {
      fail('Incomplete transaction: unexpected end of data');
    }
  }

  function readBytes(n) {
    need(n);
    const b = buf.subarray(offset, offset + n);
    offset += n;
    return b;
  }

  function readUInt32LE() {
    need(4);
    const v = buf.readUInt32LE(offset);
    offset += 4;
    return v;
  }

  function readUInt64LE() {
    need(8);
    const v = buf.readBigUInt64LE(offset);
    offset += 8;
    if (v > BigInt(Number.MAX_SAFE_INTEGER)) {
      fail('Value exceeds Number.MAX_SAFE_INTEGER');
    }
    return Number(v);
  }

  function readVarInt() {
    need(1);
    const first = buf[offset];
    offset += 1;
    if (first < 0xfd) {
      return first;
    } else if (first === 0xfd) {
      need(2);
      const v = buf.readUInt16LE(offset);
      offset += 2;
      if (v < 0xfd) {
        fail('Non-canonical VarInt (0xfd prefix with value < 0xfd)');
      }
      return v;
    } else if (first === 0xfe) {
      need(4);
      const v = buf.readUInt32LE(offset);
      offset += 4;
      if (v <= 0xffff) {
        fail('Non-canonical VarInt (0xfe prefix with value <= 0xffff)');
      }
      return v;
    } else {
      need(8);
      const v = buf.readBigUInt64LE(offset);
      offset += 8;
      if (v <= BigInt(0xffffffff)) {
        fail('Non-canonical VarInt (0xff prefix with value <= 0xffffffff)');
      }
      if (v > BigInt(Number.MAX_SAFE_INTEGER)) {
        fail('VarInt exceeds Number.MAX_SAFE_INTEGER');
      }
      return Number(v);
    }
  }

  // Version
  const version = readUInt32LE();

  // Inputs
  const inputCount = readVarInt();
  const inputs = [];
  for (let i = 0; i < inputCount; i++) {
    const txidBytes = readBytes(32);
    const txid = Buffer.from(txidBytes).reverse().toString('hex');
    const vout = readUInt32LE();
    const scriptLen = readVarInt();
    const scriptBytes = readBytes(scriptLen);
    const scriptsig = scriptBytes.toString('hex');
    const sequence = readUInt32LE();
    inputs.push({ txid, vout, scriptsig, sequence });
  }

  // Outputs
  const outputCount = readVarInt();
  const outputs = [];
  for (let i = 0; i < outputCount; i++) {
    const value = readUInt64LE();
    const scriptLen = readVarInt();
    const scriptBytes = readBytes(scriptLen);
    const scriptpubkey = scriptBytes.toString('hex');
    outputs.push({ value, scriptpubkey });
  }

  // Locktime
  const locktime = readUInt32LE();

  if (offset !== buf.length) {
    fail(`Malformed transaction: ${buf.length - offset} trailing byte(s)`);
  }

  const result = {
    version,
    input_count: inputCount,
    inputs,
    output_count: outputCount,
    outputs,
    locktime,
  };

  process.stdout.write(JSON.stringify(result, null, 2) + '\n');
}

main();
